package com.meninocoiso.bscm.data.repository

import android.util.Log
import com.meninocoiso.bscm.data.remote.ApiClient
import com.meninocoiso.bscm.data.security.SecureTokenManager
import com.meninocoiso.bscm.domain.model.User
import com.meninocoiso.bscm.domain.model.auth.AuthRequest
import com.meninocoiso.bscm.domain.model.auth.AuthResponse
import com.meninocoiso.bscm.domain.model.auth.RefreshTokenRequest
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.coroutines.cancellation.CancellationException

private const val TAG = "AuthRepository"

@Singleton
class AuthRepository @Inject constructor(
    private val apiClient: ApiClient,
    private val tokenManager: SecureTokenManager
) {

    suspend fun isLoggedIn(): Boolean = tokenManager.isLoggedIn()
    fun isLoggedInFlow(): Flow<Boolean> = tokenManager.isLoggedInFlow()

    fun authenticateWithDiscord(code: String, redirectUri: String): Flow<Result<User>> = flow {
            Log.d(TAG, "authenticateWithDiscord: Starting authentication with code=${code.take(10)}..., redirectUri=$redirectUri")

            // Retrieve the stored code_verifier for PKCE
            val codeVerifier = tokenManager.getCodeVerifier()
            if (codeVerifier == null) {
                Log.e(TAG, "authenticateWithDiscord: Code verifier not found")
                emit(Result.failure(Exception("Code verifier não encontrado. Reinicie o fluxo de autenticação.")))
                return@flow
            }

        try {
            Log.d(TAG, "authenticateWithDiscord: Code verifier found, creating auth request")
            val authRequest = AuthRequest(code, redirectUri, codeVerifier)

            Log.d(TAG, "authenticateWithDiscord: Calling API client")
            val result = apiClient.authenticateWithDiscord(authRequest)

            Log.d(TAG, "authenticateWithDiscord: API call successful, saving tokens")
            tokenManager.saveTokens(result.accessToken, result.refreshToken)

            if (result.user == null) {
                Log.e(TAG, "authenticateWithDiscord: User data is null in the response")
                emit(Result.failure(Exception("User data is null in the response")))
                return@flow
            }

            Log.d(TAG, "authenticateWithDiscord: Authentication completed successfully")
            emit(Result.success(result.user))
        } catch (t: Throwable) {
            if (t is CancellationException) {
                Log.d(TAG, "authenticateWithDiscord: Flow cancelled")
                throw t // do not convert cancellation into failure
            }
            Log.e(TAG, "authenticateWithDiscord: Error occurred - ${t.message}", t)
            emit(Result.failure(t))
        } finally {
            // Always clear code_verifier after attempt
            tokenManager.clearCodeVerifier()
        }
    }

    fun refreshAccessToken(): Flow<Result<AuthResponse>> = flow {
            val refreshToken = tokenManager.getRefreshToken()
            if (refreshToken.isNullOrEmpty()) {
                emit(Result.failure(Exception("No refresh token available")))
                return@flow
            }

        try {
            val request = RefreshTokenRequest(refreshToken)
            val newTokens = apiClient.refreshToken(request)
            tokenManager.saveTokens(newTokens.accessToken, newTokens.refreshToken)
            emit(Result.success(newTokens))
        } catch (t: Throwable) {
            if (t is kotlinx.coroutines.CancellationException) {
                Log.d(TAG, "refreshAccessToken: Flow cancelled")
                throw t
            }
            // If the refresh token is invalid, clear the tokens
            if (t.message?.contains("invalid", ignoreCase = true) == true ||
                t.message?.contains("expired", ignoreCase = true) == true
            ) {
                tokenManager.clearTokens()
            }
            emit(Result.failure(t))
        }
    }

    fun getCurrentUser(): Flow<Result<User>> = flow {
        try {
            val user = apiClient.getCurrentUser()
            emit(Result.success(user))
        } catch (t: Throwable) {
            if (t is kotlinx.coroutines.CancellationException) {
                Log.d(TAG, "getCurrentUser: Flow cancelled")
                throw t
            }
            emit(Result.failure(t))
        }
    }

    suspend fun logout() {
        tokenManager.clearTokens()
    }

    suspend fun clearPkceVerifier() { tokenManager.clearCodeVerifier() }
}

package com.meninocoiso.bscm.data.repository

import android.util.Log
import com.meninocoiso.bscm.data.remote.ApiClient
import com.meninocoiso.bscm.data.security.SecureTokenManager
import com.meninocoiso.bscm.domain.exception.AuthException
import com.meninocoiso.bscm.domain.model.User
import com.meninocoiso.bscm.domain.model.auth.AuthRequest
import com.meninocoiso.bscm.domain.model.auth.AuthResponse
import com.meninocoiso.bscm.domain.model.auth.RefreshTokenRequest
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.coroutines.cancellation.CancellationException

private const val TAG = "AuthRepository"

@Singleton
class AuthRepository @Inject constructor(
    private val apiClient: ApiClient,
    private val tokenManager: SecureTokenManager
) {
    suspend fun isLoggedIn(): Boolean = tokenManager.isLoggedIn()
    fun isLoggedInFlow(): Flow<Boolean> = tokenManager.isLoggedInFlow()

    fun authenticateWithDiscord(code: String, redirectUri: String): Flow<Result<User>> = flow {
        Log.d(TAG, "authenticateWithDiscord: Starting authentication with code=${code.take(10)}..., redirectUri=$redirectUri")
        val codeVerifier = tokenManager.getCodeVerifier()
        if (codeVerifier == null) {
            emit(Result.failure(AuthException.MissingCodeVerifier()))
            return@flow
        }
        try {
            val authRequest = AuthRequest(code, redirectUri, codeVerifier)
            val result = apiClient.authenticateWithDiscord(authRequest)
            tokenManager.saveTokens(result.accessToken, result.refreshToken)
            val user = result.user
            if (user == null) {
                emit(Result.failure(AuthException.Server("User data ausente")))
            } else {
                emit(Result.success(user))
            }
        } catch (t: Throwable) {
            if (t is CancellationException) throw t
            Log.e(TAG, "authenticateWithDiscord: Error", t)
            emit(Result.failure(mapThrowable(t)))
        } finally {
            tokenManager.clearCodeVerifier()
            tokenManager.clearOAuthState()
        }
    }

    fun refreshAccessToken(): Flow<Result<AuthResponse>> = flow {
        val refreshToken = tokenManager.getRefreshToken()
        if (refreshToken.isNullOrEmpty()) {
            emit(Result.failure(AuthException.TokenRefresh("Refresh token inexistente")))
            return@flow
        }
        try {
            val request = RefreshTokenRequest(refreshToken)
            val newTokens = apiClient.refreshToken(request)
            tokenManager.saveTokens(newTokens.accessToken, newTokens.refreshToken)
            emit(Result.success(newTokens))
        } catch (t: Throwable) {
            if (t is CancellationException) throw t
            if (t.message?.contains("invalid", true) == true || t.message?.contains("expired", true) == true) {
                tokenManager.clearTokens()
            }
            emit(Result.failure(mapThrowable(t)))
        }
    }

    fun getCurrentUser(): Flow<Result<User>> = flow {
        try {
            val user = apiClient.getCurrentUser()
            emit(Result.success(user))
        } catch (t: Throwable) {
            if (t is CancellationException) throw t
            emit(Result.failure(mapThrowable(t)))
        }
    }

    suspend fun logout() { tokenManager.clearTokens() }
    suspend fun clearPkceVerifier() { tokenManager.clearCodeVerifier() }

    private fun mapThrowable(t: Throwable): Throwable = when (t) {
        is AuthException -> t
        else -> {
            val msg = t.message ?: "Erro desconhecido"
            if (msg.contains("timeout", true)) AuthException.Network("Timeout na comunicação", t)
            else if (msg.contains("unable to resolve host", true) || msg.contains("failed to connect", true)) AuthException.Network("Falha de rede", t)
            else AuthException.Unknown(t)
        }
    }
}

package com.meninocoiso.bscm.data.security

import android.content.Context
import android.net.Uri
import androidx.browser.customtabs.CustomTabsIntent
import androidx.core.net.toUri
import java.security.MessageDigest
import java.security.SecureRandom
import javax.inject.Inject
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

class DiscordOAuth @Inject constructor(
    private val tokenManager: SecureTokenManager
) {

    // Generates a random code verifier according to PKCE spec
    @OptIn(ExperimentalEncodingApi::class)
    private fun generateCodeVerifier(): String {
        val secureRandom = SecureRandom()
        val code = ByteArray(32)
        secureRandom.nextBytes(code)

        // Base64 URL-safe without padding
        return Base64.UrlSafe.encode(code).trimEnd('=')
    }

    // Creates a code challenge (SHA256 hash of verifier, base64-url-encoded)
    @OptIn(ExperimentalEncodingApi::class)
    private fun generateCodeChallenge(codeVerifier: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(codeVerifier.toByteArray(Charsets.US_ASCII))

        // Base64 URL-safe without padding
        return Base64.UrlSafe.encode(hash).trimEnd('=')
    }

    // Starts the OAuth2 flow with PKCE
    suspend fun startDiscordOAuth(context: Context) {
        val clientId = "1329849906868912259"
        val redirectUri = "bscm://auth"
        val scope = "identify email"

        // Generate verifier and challenge
        val codeVerifier = generateCodeVerifier()
        val codeChallenge = generateCodeChallenge(codeVerifier)

        // Persist code verifier for later use
        tokenManager.saveCodeVerifier(codeVerifier)

        // Build authorization URL with PKCE parameters
        val authUrl: Uri = "https://discord.com/api/oauth2/authorize".toUri()
            .buildUpon()
            .appendQueryParameter("client_id", clientId)
            .appendQueryParameter("redirect_uri", redirectUri)
            .appendQueryParameter("response_type", "code")
            .appendQueryParameter("scope", scope)
            .appendQueryParameter("code_challenge", codeChallenge)
            .appendQueryParameter("code_challenge_method", "S256")
            .build()

        val customTabsIntent = CustomTabsIntent.Builder()
            .setShowTitle(true)
            .build()

        customTabsIntent.launchUrl(context, authUrl)
    }
}

package com.meninocoiso.bscm.data.security

import android.content.Context
import android.net.Uri
import android.util.Log
import androidx.browser.customtabs.CustomTabsIntent
import androidx.core.net.toUri
import com.meninocoiso.bscm.BuildConfig
import com.meninocoiso.bscm.domain.exception.AuthException
import java.security.MessageDigest
import java.security.SecureRandom
import javax.inject.Inject
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

class DiscordOAuth @Inject constructor(
    private val tokenManager: SecureTokenManager
) {

    private val TAG = "DiscordOAuth"

    // Generates a random code verifier according to PKCE spec
    @OptIn(ExperimentalEncodingApi::class)
    private fun generateCodeVerifier(): String {
        val secureRandom = SecureRandom()
        val code = ByteArray(32)
        secureRandom.nextBytes(code)

        // Base64 URL-safe without padding
        return Base64.UrlSafe.encode(code).trimEnd('=')
    }

    // Creates a code challenge (SHA256 hash of verifier, base64-url-encoded)
    @OptIn(ExperimentalEncodingApi::class)
    private fun generateCodeChallenge(codeVerifier: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(codeVerifier.toByteArray(Charsets.US_ASCII))

        // Base64 URL-safe without padding
        return Base64.UrlSafe.encode(hash).trimEnd('=')
    }

    // Generates random state token to mitigate CSRF
    @OptIn(ExperimentalEncodingApi::class)
    private fun generateState(): String {
        val random = SecureRandom()
        val bytes = ByteArray(16)
        random.nextBytes(bytes)
        return Base64.UrlSafe.encode(bytes).trimEnd('=')
    }

    // Starts the OAuth2 flow with PKCE + state
    suspend fun startDiscordOAuth(context: Context) {
        val clientId = BuildConfig.DISCORD_CLIENT_ID
        require(clientId.isNotBlank()) { AuthException.Server("Discord Client ID ausente").message ?: "Client ID ausente" }
        val redirectUri = "bscm://auth"
        val scope = "identify email"

        // Generate verifier and challenge
        val codeVerifier = generateCodeVerifier()
        val codeChallenge = generateCodeChallenge(codeVerifier)
        val state = generateState()

        Log.d(TAG, "Starting OAuth - saving PKCE+state")
        tokenManager.saveCodeVerifier(codeVerifier)
        tokenManager.saveOAuthState(state)

        val authUrl: Uri = "https://discord.com/api/oauth2/authorize".toUri()
            .buildUpon()
            .appendQueryParameter("client_id", clientId)
            .appendQueryParameter("redirect_uri", redirectUri)
            .appendQueryParameter("response_type", "code")
            .appendQueryParameter("scope", scope)
            .appendQueryParameter("code_challenge", codeChallenge)
            .appendQueryParameter("code_challenge_method", "S256")
            .appendQueryParameter("state", state)
            .build()

        val customTabsIntent = CustomTabsIntent.Builder()
            .setShowTitle(true)
            .build()

        customTabsIntent.launchUrl(context, authUrl)
    }
}

package com.meninocoiso.bscm.data.security

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "secure_tokens")

@Singleton
class SecureTokenManager @Inject constructor(
    @ApplicationContext private val context: Context
) {
    private val ACCESS_TOKEN_KEY = stringPreferencesKey("access_token")
    private val REFRESH_TOKEN_KEY = stringPreferencesKey("refresh_token")
    private val CODE_VERIFIER_KEY = stringPreferencesKey("code_verifier")

    suspend fun saveTokens(accessToken: String, refreshToken: String) {
        context.dataStore.edit { preferences ->
            preferences[ACCESS_TOKEN_KEY] = accessToken
            preferences[REFRESH_TOKEN_KEY] = refreshToken
        }
    }

    suspend fun getAccessToken(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[ACCESS_TOKEN_KEY] }
            .first()
    }

    suspend fun getRefreshToken(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[REFRESH_TOKEN_KEY] }
            .first()
    }

    suspend fun saveCodeVerifier(codeVerifier: String) {
        context.dataStore.edit { preferences ->
            preferences[CODE_VERIFIER_KEY] = codeVerifier
        }
    }

    suspend fun getCodeVerifier(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[CODE_VERIFIER_KEY] }
            .first()
    }

    suspend fun clearCodeVerifier() {
        context.dataStore.edit { preferences ->
            preferences.remove(CODE_VERIFIER_KEY)
        }
    }

    suspend fun clearTokens() {
        context.dataStore.edit { preferences ->
            preferences.remove(ACCESS_TOKEN_KEY)
            preferences.remove(REFRESH_TOKEN_KEY)
            preferences.remove(CODE_VERIFIER_KEY)
        }
    }

    suspend fun isLoggedIn(): Boolean {
        return getAccessToken() != null
    }

    // --- Reactive flows ----------------------------------------------------
    // Fluxo contínuo do access token (null quando não logado)
    fun accessTokenFlow(): Flow<String?> = context.dataStore.data.map { it[ACCESS_TOKEN_KEY] }
    // Fluxo booleano de estado de login
    fun isLoggedInFlow(): Flow<Boolean> = accessTokenFlow().map { it != null }
}

package com.meninocoiso.bscm.data.security

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "secure_tokens")

@Singleton
class SecureTokenManager @Inject constructor(
    @ApplicationContext private val context: Context
) {
    private val ACCESS_TOKEN_KEY = stringPreferencesKey("access_token")
    private val REFRESH_TOKEN_KEY = stringPreferencesKey("refresh_token")
    private val CODE_VERIFIER_KEY = stringPreferencesKey("code_verifier")
    private val OAUTH_STATE_KEY = stringPreferencesKey("oauth_state")

    suspend fun saveTokens(accessToken: String, refreshToken: String) {
        context.dataStore.edit { preferences ->
            preferences[ACCESS_TOKEN_KEY] = accessToken
            preferences[REFRESH_TOKEN_KEY] = refreshToken
        }
    }

    suspend fun getAccessToken(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[ACCESS_TOKEN_KEY] }
            .first()
    }

    suspend fun getRefreshToken(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[REFRESH_TOKEN_KEY] }
            .first()
    }

    suspend fun saveCodeVerifier(codeVerifier: String) {
        context.dataStore.edit { preferences ->
            preferences[CODE_VERIFIER_KEY] = codeVerifier
        }
    }

    suspend fun getCodeVerifier(): String? {
        return context.dataStore.data
            .map { preferences -> preferences[CODE_VERIFIER_KEY] }
            .first()
    }

    suspend fun clearCodeVerifier() {
        context.dataStore.edit { preferences ->
            preferences.remove(CODE_VERIFIER_KEY)
        }
    }

    // --- OAuth state (CSRF protection) ------------------------------------
    suspend fun saveOAuthState(state: String) {
        context.dataStore.edit { it[OAUTH_STATE_KEY] = state }
    }

    suspend fun getOAuthState(): String? = context.dataStore.data.map { it[OAUTH_STATE_KEY] }.first()

    suspend fun clearOAuthState() {
        context.dataStore.edit { it.remove(OAUTH_STATE_KEY) }
    }

    suspend fun clearTokens() {
        context.dataStore.edit { preferences ->
            preferences.remove(ACCESS_TOKEN_KEY)
            preferences.remove(REFRESH_TOKEN_KEY)
            preferences.remove(CODE_VERIFIER_KEY)
            preferences.remove(OAUTH_STATE_KEY)
        }
    }

    suspend fun isLoggedIn(): Boolean {
        return getAccessToken() != null
    }

    // --- Reactive flows ----------------------------------------------------
    fun accessTokenFlow(): Flow<String?> = context.dataStore.data.map { it[ACCESS_TOKEN_KEY] }
    fun isLoggedInFlow(): Flow<Boolean> = accessTokenFlow().map { it != null }
}

package com.meninocoiso.bscm.domain.exception

sealed class AuthException(message: String, cause: Throwable? = null): Exception(message, cause) {
    class UserCancelled: AuthException("Autenticação cancelada pelo usuário")
    class Timeout: AuthException("Tempo de autenticação excedido")
    class MissingCodeVerifier: AuthException("Code verifier ausente. Reinicie o login.")
    class StateMismatch: AuthException("Validação de segurança falhou (state mismatch)")
    class InvalidAuthorizationCode: AuthException("Código de autorização inválido")
    class Network(message: String, cause: Throwable? = null): AuthException(message, cause)
    class Server(message: String, cause: Throwable? = null): AuthException(message, cause)
    class TokenRefresh(message: String, cause: Throwable? = null): AuthException(message, cause)
    class Unknown(cause: Throwable? = null): AuthException("Erro desconhecido", cause)
}

package com.meninocoiso.bscm.presentation.activity

import android.os.Bundle
import android.util.Log
import androidx.activity.ComponentActivity
import androidx.activity.viewModels
import androidx.lifecycle.lifecycleScope
import com.meninocoiso.bscm.presentation.viewmodel.AuthViewModel
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch

@AndroidEntryPoint
class OAuthCallbackActivity : ComponentActivity() {

    private val authViewModel: AuthViewModel by viewModels()
    private val TAG = "OAuthCallback"

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        Log.d(TAG, "OAuth callback received")

        // Extract code or error from redirect URL
        val uri = intent.data
        if (uri != null && uri.scheme == "bscm" && uri.host == "auth") {
            Log.d(TAG, "Valid URI received: $uri")

            // Check if we have a code or an error
            val code = uri.getQueryParameter("code")
            val error = uri.getQueryParameter("error")

            when {
                // Success case: we have an authorization code
                code != null -> {
                    Log.d(TAG, "Authorization code received")
                    lifecycleScope.launch {
                        try {
                            // Send the code to the ViewModel to process
                            authViewModel.handleAuthCallback(code)
                            Log.d(TAG, "Code processed successfully")
                        } catch (e: Exception) {
                            Log.e(TAG, "Error processing authorization code", e)
                        }
                    }
                }

                // Error case: user denied access or another error occurred
                error != null -> {
                    val errorDescription = uri.getQueryParameter("error_description") ?: "Unknown error"
                    Log.e(TAG, "Authorization error: $errorDescription")
                    // Notificar o ViewModel sobre o erro, se necessário
                    // authViewModel.setError("Erro na autenticação: $errorDescription")
                }

                // Invalid or incomplete URI
                else -> {
                    Log.e(TAG, "URI without code or error")
                    // authViewModel.setError("Resposta de autenticação inválida")
                }
            }
        } else {
            Log.e(TAG, "Invalid or null URI: ${intent.data}")
            if (uri != null) {
                Log.e(TAG, "Scheme: ${uri.scheme}, Host: ${uri.host}")
            }
            // authViewModel.setError("URI de callback inválida")
        }

        // Finalizar a atividade para voltar à tela anterior
        finish()
    }
}

package com.meninocoiso.bscm.presentation.activity

import android.os.Bundle
import android.util.Log
import androidx.activity.ComponentActivity
import androidx.activity.viewModels
import androidx.lifecycle.lifecycleScope
import com.meninocoiso.bscm.presentation.viewmodel.AuthViewModel
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch

@AndroidEntryPoint
class OAuthCallbackActivity : ComponentActivity() {

    private val authViewModel: AuthViewModel by viewModels()
    private val TAG = "OAuthCallback"

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        Log.d(TAG, "OAuth callback received")

        // Extract code or error from redirect URL
        val uri = intent.data
        if (uri != null && uri.scheme == "bscm" && uri.host == "auth") {
            Log.d(TAG, "Valid URI received: $uri")

            // Check if we have a code or an error
            val code = uri.getQueryParameter("code")
            val error = uri.getQueryParameter("error")
            val state = uri.getQueryParameter("state")

            when {
                // Success case: we have an authorization code
                code != null -> {
                    Log.d(TAG, "Authorization code received; forwarding to ViewModel with state=$state")
                    lifecycleScope.launch {
                        runCatching { authViewModel.handleAuthCallback(code, state) }
                            .onFailure { e -> Log.e(TAG, "Error processing authorization code", e) }
                    }
                }

                // Error case: user denied access or another error occurred
                error != null -> {
                    val errorDescription = uri.getQueryParameter("error_description") ?: error
                    val userMessage = when (error) {
                        "access_denied" -> "Acesso negado pelo usuário"
                        else -> "Falha na autenticação: $errorDescription"
                    }
                    Log.e(TAG, "Authorization error: $errorDescription ($error)")
                    authViewModel.handleAuthError(userMessage)
                }

                // Invalid or incomplete URI
                else -> {
                    Log.e(TAG, "URI without code or error")
                    authViewModel.handleAuthError("Retorno inválido do provedor OAuth")
                }
            }
        } else {
            Log.e(TAG, "Invalid or null URI: ${intent.data}")
            uri?.let { Log.e(TAG, "Scheme: ${it.scheme}, Host: ${it.host}") }
            authViewModel.handleAuthError("Callback inválido")
        }

        // Finalizar a atividade para voltar à tela anterior
        finish()
    }
}

