package com.meninocoiso.bscm.presentation.viewmodel

import android.content.Context
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.meninocoiso.bscm.data.repository.AuthRepository
import com.meninocoiso.bscm.data.security.DiscordOAuth
import com.meninocoiso.bscm.domain.model.User
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.onCompletion
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.launch
import javax.inject.Inject

data class AuthUiState(
    val isLoading: Boolean = false,
    val isLoggedIn: Boolean = false,
    val user: User? = null,
    val error: String? = null
)

private const val TAG = "AuthViewModel"

@HiltViewModel
class AuthViewModel @Inject constructor(
    private val authRepository: AuthRepository,
    private val discordOAuth: DiscordOAuth
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    // Controle de fluxo OAuth
    private var waitingForCallback: Boolean = false
    private var oauthStartTime: Long = 0L
    private var oauthTimeoutJob = null as kotlinx.coroutines.Job?
    private companion object {
        // Ajustado para 0L para cancelar imediatamente quando usuário fecha o Custom Tab
        const val OAUTH_CANCEL_GRACE_MS = 0L
        const val OAUTH_MAX_WAIT_MS = 120_000L
    }

    init {
        checkAuthState() // carga inicial rápida
        observeLoginState() // observação contínua
    }

    private fun observeLoginState() {
        viewModelScope.launch {
            authRepository.isLoggedInFlow()
                .distinctUntilChanged()
                .collect { logged ->
                    val previous = _uiState.value.isLoggedIn
                    if (logged != previous) {
                        _uiState.value = _uiState.value.copy(isLoggedIn = logged)
                        if (logged) {
                            // Ao mudar para logado, buscar usuário
                            getCurrentUser()
                        } else {
                            // Ao deslogar, resetar estado (mantendo possíveis mensagens?)
                            _uiState.value = AuthUiState()
                        }
                    }
                }
        }
    }

    private fun checkAuthState() {
        viewModelScope.launch {
            val isLoggedIn = authRepository.isLoggedIn()
            _uiState.value = _uiState.value.copy(isLoggedIn = isLoggedIn)

            if (isLoggedIn) {
                getCurrentUser()
            }
        }
    }

    fun startDiscordOAuth(context: Context) {
        viewModelScope.launch {
            // Se já havia um fluxo pendente, cancelar
            if (waitingForCallback) {
                cancelPendingOAuth("Reiniciando fluxo de autenticação")
            }
            waitingForCallback = true
            oauthStartTime = System.currentTimeMillis()

            // Set loading and clear previous error before starting OAuth
                _uiState.value = _uiState.value.copy(isLoading = true, error = null)
            // Use runCatching so we do not accidentally swallow CancellationException
            runCatching {
                discordOAuth.startDiscordOAuth(context) // may throw if intent/custom tab cannot be launched
                scheduleOAuthTimeout()
            }.onSuccess {
                // Keep isLoading = true; the flow will effectively continue when handleAuthCallback() is invoked
            }.onFailure { e ->
                waitingForCallback = false
                oauthTimeoutJob?.cancel()
                if (e is CancellationException) {
                    // Propagate cancellation and update state accordingly
                    _uiState.value = _uiState.value.copy(
                        isLoading = false,
                        error = "Authentication cancelled"
                    )
                    throw e
                }
                Log.e(TAG, "startDiscordOAuth: Error - ${e.message}", e)
                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    error = "Error starting authentication: ${e.message}"
                )
                // Limpa verifier se falhou ao iniciar
                viewModelScope.launch { authRepository.clearPkceVerifier() }
            }
        }
    }

    private fun scheduleOAuthTimeout() {
        oauthTimeoutJob?.cancel()
        oauthTimeoutJob = viewModelScope.launch {
            kotlinx.coroutines.delay(OAUTH_MAX_WAIT_MS)
            if (waitingForCallback) {
                cancelPendingOAuth("Timeout de autenticação")
            }
        }
    }

    fun onAppResumed() {
        if (waitingForCallback) {
            // Sem período de tolerância: qualquer retorno enquanto aguardando significa cancelamento
            cancelPendingOAuth("Custom Tab fechado ou usuário retornou sem concluir")
        }
    }

    private fun cancelPendingOAuth(reason: String) {
        waitingForCallback = false
        oauthTimeoutJob?.cancel()
        viewModelScope.launch { authRepository.clearPkceVerifier() }
        _uiState.value = _uiState.value.copy(
            isLoading = false,
            error = "Authentication cancelled"
        )
        Log.d(TAG, "OAuth cancelado: $reason")
    }

    fun handleAuthCallback(code: String) {
        waitingForCallback = false
        oauthTimeoutJob?.cancel()
        if (code.isBlank()) {
            _uiState.value = _uiState.value.copy(
                isLoading = false,
                error = "Invalid authorization code"
            )
            return
        }
        viewModelScope.launch {
            authRepository.authenticateWithDiscord(code, "bscm://auth")
                .onStart {
                    if (!_uiState.value.isLoading) {
                        _uiState.value = _uiState.value.copy(isLoading = true, error = null)
                    }
                }
                .catch { e ->
                    if (e is CancellationException) {
                        _uiState.value = _uiState.value.copy(
                            isLoading = false,
                            error = "Authentication cancelled"
                        )
                        throw e
                    } else {
                        _uiState.value = _uiState.value.copy(
                            isLoading = false,
                            error = "Error during authentication: ${e.message}"
                        )
                    }
                }
                .onCompletion { cause ->
                    if (cause == null && _uiState.value.isLoading) {
                        _uiState.value = _uiState.value.copy(isLoading = false)
                    }
                }
                .collect { result ->
                    result.fold(
                        onSuccess = { user ->
                            _uiState.value = _uiState.value.copy(
                                isLoading = false,
                                isLoggedIn = true, // redundante mas garante estado imediato até o flow propagar
                                user = user,
                                error = null
                            )
                        },
                        onFailure = { ex ->
                            _uiState.value = _uiState.value.copy(
                                isLoading = false,
                                error = "Authentication failed: ${ex.message}"
                            )
                        }
                    )
                }
        }
    }

    private fun getCurrentUser() {
        viewModelScope.launch {
            authRepository.getCurrentUser()
                .onStart {
                    Log.d(TAG, "getCurrentUser: Fetching current user")
                }
                .catch { e ->
                    Log.e(TAG, "getCurrentUser: Flow exception, logging out - ${e.message}", e)
                    // If it fails to get the user, the token may be invalid
                    logout()
                }
                .collect { result ->
                    result
                        .onSuccess { user ->
                            Log.d(TAG, "getCurrentUser: User fetched = $user")
                            _uiState.value = _uiState.value.copy(user = user)
                        }
                        .onFailure { ex ->
                            Log.e(
                                TAG,
                                "getCurrentUser: Failed to fetch user (${ex.message}), logging out"
                            )
                            // If it fails to get the user, the token may be invalid
                            logout()
                        }
                }
        }
    }

    fun logout() {
        viewModelScope.launch {
                Log.d(TAG, "logout: Logging out")
            // Use runCatching for consistent error handling and to avoid swallowing CancellationException
            runCatching {
                authRepository.logout() // suspend call (if turned into a Flow later, adapt with onStart/catch/onCompletion)
            }.onSuccess {
                // Reset to initial state after successful logout
                _uiState.value = AuthUiState()
            }.onFailure { e ->
                if (e is CancellationException) {
                    Log.d(TAG, "logout: Cancelled")
                    throw e // propagate cancellation
                }
                Log.e(TAG, "logout: Error during logout - ${e.message}", e)
                _uiState.value = _uiState.value.copy(
                    error = "Error during logout: ${e.message}"
                )
            }
        }
    }

    fun clearError() {
        Log.d(TAG, "clearError: Clearing error")
        _uiState.value = _uiState.value.copy(error = null)
    }
}

package com.meninocoiso.bscm.presentation.viewmodel

import android.content.Context
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.meninocoiso.bscm.data.repository.AuthRepository
import com.meninocoiso.bscm.data.security.DiscordOAuth
import com.meninocoiso.bscm.data.security.SecureTokenManager
import com.meninocoiso.bscm.domain.exception.AuthException
import com.meninocoiso.bscm.domain.model.User
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.onCompletion
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.launch
import javax.inject.Inject

data class AuthUiState(
    val isLoading: Boolean = false,
    val isLoggedIn: Boolean = false,
    val user: User? = null,
    val error: String? = null
)

private const val TAG = "AuthViewModel"

@HiltViewModel
class AuthViewModel @Inject constructor(
    private val authRepository: AuthRepository,
    private val discordOAuth: DiscordOAuth,
    private val tokenManager: SecureTokenManager
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

    // Controle de fluxo OAuth
    private var waitingForCallback: Boolean = false
    private var oauthStartTime: Long = 0L
    private var oauthTimeoutJob = null as kotlinx.coroutines.Job?
    private companion object {
        const val OAUTH_CANCEL_GRACE_MS = 1500L // atraso para evitar cancelar antes do callback
        const val OAUTH_MAX_WAIT_MS = 120_000L
    }

    init {
        checkAuthState()
        observeLoginState()
    }

    private fun observeLoginState() {
        viewModelScope.launch {
            authRepository.isLoggedInFlow()
                .distinctUntilChanged()
                .collect { logged ->
                    val previous = _uiState.value.isLoggedIn
                    if (logged != previous) {
                        _uiState.value = _uiState.value.copy(isLoggedIn = logged)
                        if (logged) {
                            getCurrentUser()
                        } else {
                            _uiState.value = AuthUiState()
                        }
                    }
                }
        }
    }

    private fun checkAuthState() {
        viewModelScope.launch {
            val isLoggedIn = authRepository.isLoggedIn()
            _uiState.value = _uiState.value.copy(isLoggedIn = isLoggedIn)
            if (isLoggedIn) getCurrentUser()
        }
    }

    fun startDiscordOAuth(context: Context) {
        if (_uiState.value.isLoading) return // evita múltiplos cliques
        viewModelScope.launch {
            if (waitingForCallback) {
                cancelPendingOAuth("Reiniciando fluxo de autenticação")
            }
            waitingForCallback = true
            oauthStartTime = System.currentTimeMillis()
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)
            runCatching { discordOAuth.startDiscordOAuth(context); scheduleOAuthTimeout() }
                .onFailure { e ->
                    waitingForCallback = false
                    oauthTimeoutJob?.cancel()
                    if (e is CancellationException) throw e
                    Log.e(TAG, "startDiscordOAuth: Error", e)
                    _uiState.value = _uiState.value.copy(isLoading = false, error = mapError(e))
                    viewModelScope.launch { authRepository.clearPkceVerifier() }
                }
        }
    }

    private fun scheduleOAuthTimeout() {
        oauthTimeoutJob?.cancel()
        oauthTimeoutJob = viewModelScope.launch {
            kotlinx.coroutines.delay(OAUTH_MAX_WAIT_MS)
            if (waitingForCallback) cancelPendingOAuth("Timeout de autenticação")
        }
    }

    fun onAppResumed() {
        if (waitingForCallback) {
            // Aguardar pequeno delay para permitir que o deep link abra a activity de callback
            viewModelScope.launch {
                kotlinx.coroutines.delay(OAUTH_CANCEL_GRACE_MS)
                if (waitingForCallback) {
                    cancelPendingOAuth("Custom Tab fechado ou usuário retornou sem concluir")
                }
            }
        }
    }

    private fun cancelPendingOAuth(reason: String) {
        waitingForCallback = false
        oauthTimeoutJob?.cancel()
        viewModelScope.launch {
            authRepository.clearPkceVerifier()
            tokenManager.clearOAuthState()
        }
        if (_uiState.value.isLoading) {
            _uiState.value = _uiState.value.copy(isLoading = false, error = AuthException.UserCancelled().message)
        }
        Log.d(TAG, "OAuth cancelado: $reason")
    }

    fun handleAuthCallback(code: String?, state: String?) {
        waitingForCallback = false
        oauthTimeoutJob?.cancel()
        viewModelScope.launch {
            if (code.isNullOrBlank()) {
                _uiState.value = _uiState.value.copy(isLoading = false, error = AuthException.InvalidAuthorizationCode().message)
                return@launch
            }
            val storedState = tokenManager.getOAuthState()
            if (storedState == null) {
                _uiState.value = _uiState.value.copy(isLoading = false, error = AuthException.Timeout().message)
                return@launch
            }
            if (state == null || state != storedState) {
                tokenManager.clearOAuthState()
                _uiState.value = _uiState.value.copy(isLoading = false, error = AuthException.StateMismatch().message)
                return@launch
            }
            tokenManager.clearOAuthState()
            authRepository.authenticateWithDiscord(code, "bscm://auth")
                .onStart { if (!_uiState.value.isLoading) _uiState.value = _uiState.value.copy(isLoading = true, error = null) }
                .catch { e ->
                    if (e is CancellationException) throw e
                    _uiState.value = _uiState.value.copy(isLoading = false, error = mapError(e))
                }
                .onCompletion { cause -> if (cause == null && _uiState.value.isLoading) _uiState.value = _uiState.value.copy(isLoading = false) }
                .collect { result ->
                    result.fold(
                        onSuccess = { user ->
                            _uiState.value = _uiState.value.copy(isLoading = false, isLoggedIn = true, user = user, error = null)
                        },
                        onFailure = { ex ->
                            _uiState.value = _uiState.value.copy(isLoading = false, error = mapError(ex))
                        }
                    )
                }
        }
    }

    private fun getCurrentUser() {
        viewModelScope.launch {
            authRepository.getCurrentUser()
                .onStart { Log.d(TAG, "getCurrentUser: Fetching current user") }
                .catch { e ->
                    if (e is CancellationException) throw e
                    Log.e(TAG, "getCurrentUser: error", e)
                    logout()
                }
                .collect { result ->
                    result.onSuccess { user -> _uiState.value = _uiState.value.copy(user = user) }
                        .onFailure { logout() }
                }
        }
    }

    fun logout() {
        viewModelScope.launch {
            runCatching { authRepository.logout() }
                .onSuccess { _uiState.value = AuthUiState() }
                .onFailure { e -> if (e !is CancellationException) _uiState.value = _uiState.value.copy(error = mapError(e)) else throw e }
        }
    }

    fun clearError() { _uiState.value = _uiState.value.copy(error = null) }

    fun handleAuthError(message: String) {
        waitingForCallback = false
        oauthTimeoutJob?.cancel()
        _uiState.value = _uiState.value.copy(isLoading = false, error = message)
        viewModelScope.launch {
            authRepository.clearPkceVerifier()
            tokenManager.clearOAuthState()
        }
    }

    private fun mapError(t: Throwable): String = when (t) {
        is AuthException -> t.message ?: "Erro de autenticação"
        else -> t.message ?: "Erro desconhecido"
    }
}
